cypress_script:
describe('Product Image Alt-Texts and Accessible Form Fields', () => {
  it('should display product images with correct alt-texts', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="item-0-title-link"]').should('be.visible');
    // Assume alt-text for the first item is 'Sauce Labs Bike Light'
    cy.get('img[data-test="open-menu"]').should('have.attr', 'alt', 'Open Menu');
  });

  it('should not change URL when accessing the page directly', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.url().should('eq', 'https://www.saucedemo.com/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Image Alt-Texts and Accessible Form Fields', () => {
  test('should display product images with correct alt-texts', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.locator('[data-test="item-0-title-link"]').first()).toBeVisible();
    // Assume alt-text for the first item is 'Sauce Labs Bike Light'
    const openMenuImage = page.locator('img[data-test="open-menu"]');
    await expect(openMenuImage).toHaveAttribute('alt', 'Open Menu');
  });

  test('should not change URL when accessing the page directly', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.url()).toBe('https://www.saucedemo.com/inventory.html');
  });
});
